<?php $pageTitle='Reports';$attendanceTotal=array_sum(array_map(static fn($r)=>(int)$r['total'],$attendance));$maxProgramme=max(1,...array_map(static fn($r)=>(int)$r['student_count'],$programmeCounts)); ?>
<div class="gov-page reports-page gov-enter"><section class="report-hero"><div><div class="gov-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="44" height="44"><span>Gautam Buddha University<br><b>Operational reporting</b></span></div><h1>Reports and exports</h1><p>Review validated university totals and download operational datasets for official analysis.</p></div><div class="report-exports"><span>Export datasets</span><a href="<?= e(url('reports/students.csv')) ?>"><span class="gov-icon icon-download" aria-hidden="true"></span>Students CSV</a><a href="<?= e(url('reports/attendance.csv')) ?>"><span class="gov-icon icon-download" aria-hidden="true"></span>Attendance CSV</a><a href="<?= e(url('reports/invigilation.csv')) ?>"><span class="gov-icon icon-download" aria-hidden="true"></span>Duties CSV</a><a href="<?= e(url('reports/unallocated.csv')) ?>"><span class="gov-icon icon-download" aria-hidden="true"></span>Exceptions CSV</a></div></section><section class="report-metrics"><div><span class="gov-icon icon-students" aria-hidden="true"></span><p>Students<strong><?= number_format($totals['students']) ?></strong><small>Validated records</small></p></div><div><span class="gov-icon icon-faculty" aria-hidden="true"></span><p>Active faculty<strong><?= number_format($totals['faculty']) ?></strong><small>Available staff</small></p></div><div><span class="gov-icon icon-seat" aria-hidden="true"></span><p>Usable seats<strong><?= number_format($totals['usable_seats']) ?></strong><small><?= number_format($totals['rooms']) ?> active rooms</small></p></div><div><span class="gov-icon icon-plan" aria-hidden="true"></span><p>Published plans<strong><?= number_format($totals['published_allocations']) ?></strong><small><?= number_format($totals['cycles']) ?> exam cycles</small></p></div></section><div class="report-grid"><section class="programme-report"><header><h2>Students by programme</h2><p>Current student distribution across programme codes.</p></header><?php if($programmeCounts):?><div><?php foreach($programmeCounts as $i=>$row):$percent=(int)round((int)$row['student_count']/$maxProgramme*100);?><article style="--gov-order:<?= $i ?>"><span><?= e($row['code']) ?></span><div><strong><?= e($row['name']) ?></strong><i><b style="--report-width:<?= $percent ?>%"></b></i></div><em><?= number_format((int)$row['student_count']) ?></em></article><?php endforeach;?></div><?php else:?><div class="gov-empty compact"><h2>No programme data</h2></div><?php endif;?></section><section class="attendance-report"><header><h2>Attendance status</h2><p><?= number_format($attendanceTotal) ?> total attendance records.</p></header><?php if($attendance):?><div class="attendance-breakdown"><?php foreach($attendance as $i=>$row):$percent=$attendanceTotal?(int)round((int)$row['total']/$attendanceTotal*100):0;?><article style="--gov-order:<?= $i ?>"><span class="attendance-status <?= e($row['status']) ?>"><i aria-hidden="true"></i></span><div><strong><?= e(ucwords(str_replace('_',' ',$row['status']))) ?></strong><small><?= $percent ?>% of records</small></div><b><?= number_format((int)$row['total']) ?></b></article><?php endforeach;?></div><?php else:?><div class="gov-empty compact"><h2>No attendance data</h2></div><?php endif;?></section></div></div>
